hc+=['<section class="section wrap" id="process">'+heading('BUILT AROUND YOUR FLOOR','You pick the voices. We do the rest.')+'<p class="section-intro">Your development team is running a campaign, not a production. The process is built to take as little from them as possible.</p><div class="process-grid">'+''.join('<article><span>0'+str(i+1)+'</span><h3>'+t+'</h3>'+p(d)+'</article>' for i,(t,d) in enumerate(hc_process))+'</div><p class="guarantee">First cut in fourteen days. <strong>If it is late, you do not pay.</strong><span>The clock pauses while we wait on your approvals.</span></p></section>']
